package com.tablebridge;

import java.sql.*;
import java.nio.file.*;
import java.util.*;
import java.math.BigDecimal;

/** Both endpoints must be task-owned local instances, checked before any schema writes. */
public final class CrossIntegration {
    static int checks;
    static final List<String> FIELDS=List.of("id","amount","note","payload","created","enabled");
    static void check(boolean value,String reason){checks++;if(!value)throw new AssertionError(reason);}
    public static void main(String[] args){try{run(args);}catch(Throwable failure){failure.printStackTrace();System.exit(1);}}
    private static void run(String[] args)throws Exception{
        try(Connection mysql=DriverManager.getConnection("jdbc:mysql://127.0.0.1:33316/?allowPublicKeyRetrieval=true&useSSL=false&serverTimezone=UTC","root","");Connection pg=DriverManager.getConnection("jdbc:postgresql://127.0.0.1:33317/postgres",System.getProperty("user.name"),"")){
            verifyDirectory(mysql,"SELECT @@datadir",args[0]);verifyDirectory(pg,"SHOW data_directory",args[1]);
            RowCopier.execute(mysql,"SET SESSION sql_mode='STRICT_ALL_TABLES,NO_AUTO_VALUE_ON_ZERO'");RowCopier.execute(pg,"SET TIME ZONE 'UTC'");
            RowCopier.execute(mysql,"DROP DATABASE IF EXISTS tb_matrix");RowCopier.execute(mysql,"CREATE DATABASE tb_matrix CHARACTER SET utf8mb4");
            RowCopier.execute(pg,"DROP SCHEMA IF EXISTS tb_matrix CASCADE");RowCopier.execute(pg,"CREATE SCHEMA tb_matrix");
            try{
                RowCopier.execute(mysql,"CREATE TABLE tb_matrix.source(id bigint PRIMARY KEY AUTO_INCREMENT,amount decimal(20,4),note varchar(100),payload blob,created datetime(6),enabled boolean)");
                RowCopier.execute(pg,"CREATE TABLE tb_matrix.source(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,amount numeric(20,4),note varchar(100),payload bytea,created timestamp(6),enabled boolean)");
                seed(mysql,Engine.MYSQL);seed(pg,Engine.POSTGRES);
                exercise(mysql,pg,Engine.MYSQL,Engine.POSTGRES,"from_mysql",false);
                exercise(pg,mysql,Engine.POSTGRES,Engine.MYSQL,"from_pg",false);
                exercise(mysql,pg,Engine.MYSQL,Engine.POSTGRES,"remote_mysql",true);
                exercise(pg,mysql,Engine.POSTGRES,Engine.MYSQL,"remote_pg",true);
                SyncPreviewIntegration.run(mysql,pg,Engine.MYSQL,Engine.POSTGRES,false,"mysql_pg");
                SyncPreviewIntegration.run(pg,mysql,Engine.POSTGRES,Engine.MYSQL,false,"pg_mysql");
                SyncPreviewIntegration.run(mysql,pg,Engine.MYSQL,Engine.POSTGRES,true,"remote_mysql_pg");
                SyncPreviewIntegration.run(pg,mysql,Engine.POSTGRES,Engine.MYSQL,true,"remote_pg_mysql");
                SyncPreviewIntegration.run(mysql,mysql,Engine.MYSQL,Engine.MYSQL,false,"mysql_same");
                SyncPreviewIntegration.run(pg,pg,Engine.POSTGRES,Engine.POSTGRES,false,"pg_same");
                durable(pg,Engine.POSTGRES);durable(mysql,Engine.MYSQL);
                deferredCycles(pg);RecoveryIntegration.run(pg,Engine.POSTGRES);RecoveryIntegration.run(mysql,Engine.MYSQL);RecoveryIntegration.nativeStage(pg,Engine.POSTGRES);RecoveryIntegration.nativeStage(mysql,Engine.MYSQL);
                specialNative(pg);
                clock(pg,mysql);
                zoned(pg);
                nonTableObjects(pg,mysql);
                fullStructure(pg,mysql);
                json(pg,mysql);
                jsonPrecision(pg,mysql);
                RowCopier.execute(pg,"CREATE TABLE tb_matrix.complex(id bigint PRIMARY KEY,labels text[])");RowCopier.execute(pg,"INSERT INTO tb_matrix.complex VALUES(1,ARRAY['中文','a,b','quote\"'])");
                var complex=CrossEngineDdl.build(Engine.POSTGRES,Engine.MYSQL,"tb_matrix","complex",List.of(col("id","bigint",Types.BIGINT,19,0,false),col("labels","text[]",Types.ARRAY,0,0,false)),List.of("id"),Map.of("labels",new FieldMapping(Engine.MYSQL,"longtext",true,false)));
                RowCopier.execute(mysql,complex.sql());pg.setAutoCommit(false);mysql.setAutoCommit(false);
                check(RowCopier.copy(pg,mysql,Engine.POSTGRES,Engine.MYSQL,"tb_matrix.complex","tb_matrix.complex",List.of("id","labels"),false,complex.columns().stream().map(TransferPlan.Column::targetType).toList(),()->{},n->{})==1,"explicit PostgreSQL array-to-text mapping copies");
                try(Statement q=pg.createStatement();ResultSet source=q.executeQuery("SELECT labels::text FROM tb_matrix.complex");Statement t=mysql.createStatement();ResultSet target=t.executeQuery("SELECT labels FROM tb_matrix.complex")){check(source.next()&&target.next()&&source.getString(1).equals(target.getString(1)),"array textual representation retained exactly");}
                mysql.rollback();pg.rollback();mysql.setAutoCommit(true);pg.setAutoCommit(true);
            }finally{if(!mysql.getAutoCommit())mysql.rollback();if(!pg.getAutoCommit())pg.rollback();mysql.setAutoCommit(true);pg.setAutoCommit(true);RowCopier.execute(mysql,"DROP DATABASE tb_matrix");RowCopier.execute(pg,"DROP SCHEMA tb_matrix CASCADE");}
        }
        String result="PASS "+checks+" real MySQL/PostgreSQL checks; four JDBC/native driver transfers, 603 rows each; isolated schemas cleaned.\n";Files.writeString(Path.of(args[2]),result);System.out.print(result);System.exit(0);
    }
    static void deferredCycles(Connection pg)throws Exception{
        RowCopier.execute(pg,"CREATE TABLE tb_matrix.cycle_a(id integer PRIMARY KEY,b integer)");RowCopier.execute(pg,"CREATE TABLE tb_matrix.cycle_b(id integer PRIMARY KEY,a integer REFERENCES tb_matrix.cycle_a(id) DEFERRABLE INITIALLY IMMEDIATE)");RowCopier.execute(pg,"ALTER TABLE tb_matrix.cycle_a ADD CONSTRAINT cycle_a_b FOREIGN KEY(b) REFERENCES tb_matrix.cycle_b(id) DEFERRABLE INITIALLY IMMEDIATE");pg.setAutoCommit(false);
        check(SyncDependencies.order(pg,Engine.POSTGRES,"tb_matrix",List.of("cycle_a","cycle_b")).size()==2,"deferrable cycle accepted with constraints delayed");RowCopier.execute(pg,"INSERT INTO tb_matrix.cycle_a VALUES(1,1)");RowCopier.execute(pg,"INSERT INTO tb_matrix.cycle_b VALUES(1,1)");pg.commit();pg.setAutoCommit(true);
        RowCopier.execute(pg,"ALTER TABLE tb_matrix.cycle_a ALTER CONSTRAINT cycle_a_b NOT DEFERRABLE");pg.setAutoCommit(false);boolean refused=false;try{SyncDependencies.order(pg,Engine.POSTGRES,"tb_matrix",List.of("cycle_a","cycle_b"));}catch(SQLException expected){refused=true;}check(refused,"nondeferrable cycle rejected before target DML");pg.rollback();pg.setAutoCommit(true);
    }
    static void specialNative(Connection pg)throws Exception{
        RowCopier.execute(pg,"CREATE TYPE tb_matrix.pair AS (label text,amount numeric)");
        RowCopier.execute(pg,"CREATE TABLE tb_matrix.special_src(id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,labels text[],pair tb_matrix.pair,clock timetz,xml_value xml)");
        RowCopier.execute(pg,"CREATE TABLE tb_matrix.special_dst(LIKE tb_matrix.special_src INCLUDING ALL)");
        RowCopier.execute(pg,"INSERT INTO tb_matrix.special_src(labels,pair,clock,xml_value) VALUES(ARRAY['a,b','中文',NULL],ROW('q',123.450), '12:34:56.123456+05:30','<item>中文</item>'),(NULL,NULL,NULL,NULL)");
        List<String> fields=List.of("id","labels","pair","clock","xml_value");List<Integer> types=List.of(Types.INTEGER,Types.ARRAY,Types.STRUCT,Types.TIME_WITH_TIMEZONE,Types.SQLXML);
        pg.setAutoCommit(false);check(RowCopier.copy(pg,pg,Engine.POSTGRES,Engine.POSTGRES,"tb_matrix.special_src","tb_matrix.special_dst",fields,true,types,()->{},n->{})==2,"native PG complex/timezone/identity transport");
        check(RowDigest.read(pg,Engine.POSTGRES,"tb_matrix.special_src",fields,types,()->{}).equals(RowDigest.read(pg,Engine.POSTGRES,"tb_matrix.special_dst",fields,types,()->{})),"native PG arrays composite xml timetz and null fidelity");pg.commit();pg.setAutoCommit(true);
    }
    static void durable(Connection c,Engine engine)throws Exception{
        if(engine==Engine.MYSQL)c.setCatalog("tb_matrix");
        String src=engine.qualified("tb_matrix","durable_source"),dst=engine.qualified("tb_matrix","durable_target");
        RowCopier.execute(c,"CREATE TABLE "+src+"(id integer PRIMARY KEY,note varchar(40))");RowCopier.execute(c,"CREATE TABLE "+dst+"(id integer PRIMARY KEY,note varchar(40) UNIQUE)");
        try(PreparedStatement p=c.prepareStatement("INSERT INTO "+src+" VALUES(?,?)")){for(int i=1;i<=601;i++){p.setInt(1,i);p.setString(2,"value-"+i);p.addBatch();}p.executeBatch();}
        RowCopier.execute(c,"INSERT INTO "+dst+" VALUES(1,'old'),(900,'retain')");c.setAutoCommit(false);
        String id=UUID.randomUUID().toString();var spec=new ResumableTable.Spec(src,dst,List.of("id","note"),List.of("id"),List.of(Types.INTEGER,Types.VARCHAR),false,ExistingPolicy.UPSERT);
        var job=new ResumableTable(c,engine,"tb_matrix",id,false,"fixture",()->{},line->{});
        boolean stopped=false;try{job.load(0,c,engine,spec,n->{if(n==500)throw new IllegalStateException("injected interruption");});}catch(IllegalStateException expected){stopped=true;}
        check(stopped&&job.get(0).rows()==500,"durable checkpoint committed before interruption "+engine);
        check(TargetValidation.count(c,dst,engine)==2,"target unchanged before staged snapshot complete "+engine);
        RowCopier.execute(c,"UPDATE "+src+" SET note='changed' WHERE id=601");c.commit();boolean changedRejected=false;
        try{job.load(0,c,engine,spec,n->{});}catch(SQLException expected){changedRejected=expected.getMessage().contains("来源已变化");}
        check(changedRejected&&TargetValidation.count(c,dst,engine)==2,"source change refuses mixed snapshot without target writes "+engine);
        RowCopier.execute(c,"UPDATE "+src+" SET note='value-601' WHERE id=601");c.commit();
        job=new ResumableTable(c,engine,"tb_matrix",id,true,"fixture",()->{},line->{});check(job.load(0,c,engine,spec,n->{})==601,"resume final 101 rows without duplicating first 500 "+engine);
        RowCopier.execute(c,"UPDATE "+dst+" SET note='value-9' WHERE id=900");c.commit();boolean uniqueRejected=false;
        try{job.apply(0,spec,false);}catch(SQLException expected){uniqueRejected=true;c.rollback();}
        check(uniqueRejected&&job.get(0).phase().equals("READY"),"secondary unique conflict never updates unrelated target key "+engine);
        RowCopier.execute(c,"UPDATE "+dst+" SET note='retain' WHERE id=900");c.commit();
        job.apply(0,spec,false);c.rollback();check(job.get(0).phase().equals("READY")&&TargetValidation.count(c,dst,engine)==2,"apply and checkpoint rolled back together "+engine);
        job.apply(0,spec,false);job.verify(0,spec);c.commit();check(TargetValidation.count(c,dst,engine)==602,"upsert retains unmatched target rows "+engine);job=new ResumableTable(c,engine,"tb_matrix",id,true,"fixture",()->{},line->{});check(job.apply(0,spec,false)==0,"reloaded APPLIED marker prevents duplicate DML after commit "+engine);c.rollback();
        try(Statement p=c.createStatement();ResultSet r=p.executeQuery("SELECT note FROM "+dst+" WHERE id=1")){check(r.next()&&r.getString(1).equals("value-1"),"upsert updates matching key "+engine);}
        job.cleanup(List.of(0));
        id=UUID.randomUUID().toString();spec=new ResumableTable.Spec(src,dst,List.of("id","note"),List.of("id"),List.of(Types.INTEGER,Types.VARCHAR),false,ExistingPolicy.MIRROR);job=new ResumableTable(c,engine,"tb_matrix",id,false,"mirror",()->{},line->{});job.load(0,c,engine,spec,n->{});job.apply(0,spec,true);job.verify(0,spec);c.commit();check(TargetValidation.count(c,dst,engine)==601,"mirror deletes only missing keys "+engine);job.cleanup(List.of(0));c.setAutoCommit(true);
        String parent=engine.qualified("tb_matrix","sync_parent"),child=engine.qualified("tb_matrix","sync_child");RowCopier.execute(c,"CREATE TABLE "+parent+"(id integer PRIMARY KEY)");RowCopier.execute(c,"CREATE TABLE "+child+"(id integer PRIMARY KEY,parent_id integer REFERENCES "+parent+"(id))");
        // MySQL requires an explicit table constraint rather than an inline REFERENCES clause.
        if(engine==Engine.MYSQL)RowCopier.execute(c,"ALTER TABLE "+child+" ADD CONSTRAINT sync_parent_fk FOREIGN KEY(parent_id) REFERENCES "+parent+"(id)");
        check(SyncDependencies.order(c,engine,"tb_matrix",List.of("sync_child","sync_parent")).equals(List.of(1,0)),"actual imported keys order parent before child "+engine);

    }
    static void fullStructure(Connection pg,Connection mysql)throws Exception{
        String separator="\n"+TableStructureSql.SEPARATOR+"\n";
        var pgStructure=TableStructureSql.validate(Engine.POSTGRES,"tb_matrix","structured","CREATE TABLE tb_matrix.structured(id integer PRIMARY KEY,label text COLLATE \"C\",payload jsonb)"+separator+"CREATE INDEX structured_expr ON tb_matrix.structured(lower(label)) WHERE id > 0"+separator+"CREATE INDEX structured_gin ON tb_matrix.structured USING gin(payload)"+separator+"CREATE INDEX structured_cover ON tb_matrix.structured(id) INCLUDE(label)"+separator+"CREATE TRIGGER audit BEFORE INSERT ON tb_matrix.structured FOR EACH ROW EXECUTE FUNCTION tb_matrix.structure_audit()");
        RowCopier.execute(pg,"CREATE FUNCTION tb_matrix.structure_audit() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN NEW.label := NEW.label || '-trigger'; RETURN NEW; END$$");
        RowCopier.execute(pg,pgStructure.create());RowCopier.execute(pg,"INSERT INTO tb_matrix.structured VALUES(1,'original','{}')");
        for(int phase=0;phase<3;phase++)for(String sql:pgStructure.after())if(CrossStructure.phase(sql)==phase)RowCopier.execute(pg,sql);
        RowCopier.execute(pg,"INSERT INTO tb_matrix.structured VALUES(2,'later','{}')");
        try(Statement s=pg.createStatement();ResultSet r=s.executeQuery("SELECT label FROM tb_matrix.structured ORDER BY id")){check(r.next()&&r.getString(1).equals("original"),"PG initial data imported before trigger creation");check(r.next()&&r.getString(1).equals("later-trigger"),"PG copied trigger executes on subsequent writes");}
        try(Statement s=pg.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM pg_indexes WHERE schemaname='tb_matrix' AND tablename='structured' AND indexname <> 'auto_abs' AND (indexdef LIKE '%WHERE%' OR indexdef LIKE '%USING gin%' OR indexdef LIKE '%INCLUDE%')")){check(r.next()&&r.getInt(1)==3,"PG partial expression GIN and covering index definitions retained");}
        try(Statement s=pg.createStatement();ResultSet r=s.executeQuery("SELECT c.collname FROM pg_attribute a JOIN pg_collation c ON c.oid=a.attcollation WHERE a.attrelid='tb_matrix.structured'::regclass AND a.attname='label'")){check(r.next()&&r.getString(1).equals("C"),"PG column collation retained");}
        var myStructure=TableStructureSql.validate(Engine.MYSQL,"tb_matrix","structured","CREATE TABLE `tb_matrix`.`structured`(id int PRIMARY KEY,label varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin)"+separator+"CREATE INDEX expr ON `tb_matrix`.`structured` ((lower(label)))"+separator+"CREATE INDEX prefix_idx ON `tb_matrix`.`structured` (label(12) DESC)"+separator+"CREATE TRIGGER `tb_matrix`.`structured_audit` BEFORE INSERT ON `tb_matrix`.`structured` FOR EACH ROW BEGIN SET NEW.label = CONCAT(NEW.label,'-trigger'); END;");
        RowCopier.execute(mysql,myStructure.create());RowCopier.execute(mysql,"INSERT INTO tb_matrix.structured VALUES(1,'original')");
        for(int phase=0;phase<3;phase++)for(String sql:myStructure.after())if(CrossStructure.phase(sql)==phase)RowCopier.execute(mysql,sql);
        RowCopier.execute(mysql,CrossStructure.portableIndex(Engine.MYSQL,"tb_matrix","structured",new CrossStructure.Index("auto_lower",List.of("upper(label)"),List.of(false),false),null,Set.of("label")));
        RowCopier.execute(pg,CrossStructure.portableIndex(Engine.POSTGRES,"tb_matrix","structured",new CrossStructure.Index("auto_abs",List.of("abs(id)"),List.of(false),false),"id > 0",Set.of("id")));
        check(TargetValidation.created(mysql,Engine.MYSQL,"tb_matrix.structured",List.of(new TransferPlan.Column("id",false,Types.INTEGER),new TransferPlan.Column("label",false,Types.VARCHAR))).types().equals(List.of(Types.INTEGER,Types.VARCHAR)),"created structure metadata agrees with explicit field mappings");
        check(TargetValidation.created(mysql,Engine.MYSQL,"tb_matrix.structured",List.of(new TransferPlan.Column("id",false))).types().equals(List.of(Types.INTEGER)),"same-engine manual structure resolves unspecified native column type from created metadata");
        boolean mismatch=false;try{TargetValidation.created(mysql,Engine.MYSQL,"tb_matrix.structured",List.of(new TransferPlan.Column("label",false,Types.TIMESTAMP_WITH_TIMEZONE)));}catch(SQLException expected){mismatch=true;}check(mismatch,"manual table definition cannot silently discard mapped timezone type");
        RowCopier.execute(mysql,"INSERT INTO tb_matrix.structured VALUES(2,'later')");
        try(Statement s=mysql.createStatement();ResultSet r=s.executeQuery("SELECT label FROM tb_matrix.structured ORDER BY id")){check(r.next()&&r.getString(1).equals("original"),"MySQL initial rows untouched by later trigger");check(r.next()&&r.getString(1).equals("later-trigger"),"MySQL copied trigger executes");}
        try(Statement s=mysql.createStatement();ResultSet r=s.executeQuery("SELECT COLLATION_NAME FROM information_schema.columns WHERE table_schema='tb_matrix' AND table_name='structured' AND column_name='label'")){check(r.next()&&r.getString(1).equals("utf8mb4_bin"),"MySQL collation retained");}
        try(Statement s=mysql.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema='tb_matrix' AND table_name='structured' AND ((index_name='expr' AND expression IS NOT NULL) OR (index_name='prefix_idx' AND sub_part=12 AND collation='D'))")){check(r.next()&&r.getInt(1)==2,"MySQL functional and descending prefix indexes retained");}
    }
    static void json(Connection pg,Connection mysql)throws Exception{
        RowCopier.execute(pg,"CREATE TABLE tb_matrix.json_values(id integer PRIMARY KEY,payload jsonb)");
        RowCopier.execute(mysql,"CREATE TABLE tb_matrix.json_values(id integer PRIMARY KEY,payload json)");
        RowCopier.execute(pg,"INSERT INTO tb_matrix.json_values VALUES(1,'{\"large\":1234.125,\"a\":[true,null,\"中文\"]}')");
        RowCopier.execute(mysql,"INSERT INTO tb_matrix.json_values VALUES(1,'{\"a\":[true,null,\"中文\"],\"large\":1234.125}')");
        var fields=List.of("id","payload");var types=List.of(Types.INTEGER,Types.OTHER);
        var expected=RowDigest.read(pg,Engine.POSTGRES,"tb_matrix.json_values",fields,types,()->{});
        check(expected.equals(RowDigest.read(mysql,Engine.MYSQL,"tb_matrix.json_values",fields,types,()->{})),"JSON digest ignores object ordering and whitespace");
        RowCopier.execute(mysql,"UPDATE tb_matrix.json_values SET payload=JSON_SET(payload,'$.large',CAST('1234.125001' AS DECIMAL(30,6)))");
        check(!expected.equals(RowDigest.read(mysql,Engine.MYSQL,"tb_matrix.json_values",fields,types,()->{})),"JSON digest catches numeric differences");
    }
    static void jsonPrecision(Connection pg,Connection mysql)throws Exception{
        RowCopier.execute(pg,"CREATE TABLE tb_matrix.json_precise(id integer PRIMARY KEY,payload jsonb)");
        RowCopier.execute(pg,"INSERT INTO tb_matrix.json_precise VALUES(1,'{\"value\":1234567890123456789.123456}')");
        var ddl=CrossEngineDdl.build(Engine.POSTGRES,Engine.MYSQL,"tb_matrix","json_precise",List.of(col("id","integer",Types.INTEGER,10,0,false),col("payload","jsonb",Types.OTHER,0,0,false)),List.of("id"));
        RowCopier.execute(mysql,ddl.sql());mysql.setAutoCommit(false);pg.setAutoCommit(false);
        var fields=List.of("id","payload");var types=ddl.columns().stream().map(TransferPlan.Column::targetType).toList();
        check(RowCopier.copy(pg,mysql,Engine.POSTGRES,Engine.MYSQL,"tb_matrix.json_precise","tb_matrix.json_precise",fields,false,types,()->{},n->{})==1,"JSON precise table copies using lossless default mapping");
        check(RowDigest.read(pg,Engine.POSTGRES,"tb_matrix.json_precise",fields,types,()->{}).equals(RowDigest.read(mysql,Engine.MYSQL,"tb_matrix.json_precise",fields,types,()->{})),"JSON high precision survives text mapping exactly");
        mysql.rollback();pg.rollback();mysql.setAutoCommit(true);pg.setAutoCommit(true);
    }
    static void nonTableObjects(Connection pg,Connection mysql)throws Exception{
        var pgNumber=new CrossEngineDdl.Column("n","numeric(10,2)",Types.NUMERIC,10,2,false,false,null,false);
        var myNumber=new CrossEngineDdl.Column("n","decimal(10,2)",Types.DECIMAL,10,2,false,false,null,false);
        String mysqlFunction=PortableRoutine.create(Engine.POSTGRES,Engine.MYSQL,"tb_matrix","twice",List.of(new PortableRoutine.Argument("a",pgNumber)),pgNumber,"CREATE FUNCTION src.twice(a numeric) RETURNS numeric LANGUAGE sql AS $$SELECT a * 2$$");
        String pgFunction=PortableRoutine.create(Engine.MYSQL,Engine.POSTGRES,"tb_matrix","twice",List.of(new PortableRoutine.Argument("a",myNumber)),myNumber,"CREATE FUNCTION twice(a DECIMAL(10,2)) RETURNS DECIMAL(10,2) RETURN a * 2");
        RowCopier.execute(mysql,mysqlFunction);RowCopier.execute(pg,pgFunction);
        for(Connection target:List.of(mysql,pg))try(Statement query=target.createStatement();ResultSet rs=query.executeQuery("SELECT tb_matrix.twice(2.50),tb_matrix.twice(NULL)")){check(rs.next()&&rs.getBigDecimal(1).compareTo(new BigDecimal("5.00"))==0&&rs.getBigDecimal(2)==null,"converted scalar function invocation and NULL");}
        String manualMysql=CustomObjectSql.validate(Engine.MYSQL,"tb_matrix","manual_procedure","PROCEDURE","CREATE PROCEDURE `tb_matrix`.`manual_procedure`() BEGIN SELECT 42 AS value; END;");
        String manualPg=CustomObjectSql.validate(Engine.POSTGRES,"tb_matrix","manual_procedure","PROCEDURE","CREATE PROCEDURE \"tb_matrix\".\"manual_procedure\"() LANGUAGE plpgsql AS $$BEGIN NULL; END;$$;");
        RowCopier.execute(mysql,manualMysql);RowCopier.execute(pg,manualPg);
        try(Statement call=mysql.createStatement();ResultSet rs=call.executeQuery("CALL tb_matrix.manual_procedure()")){check(rs.next()&&rs.getInt(1)==42,"manual converted MySQL procedure invokes");}
        RowCopier.execute(pg,"CALL tb_matrix.manual_procedure()");check(true,"manual converted PG procedure invokes");
        var sequence=new PortableSequence.Spec(java.math.BigInteger.valueOf(21),java.math.BigInteger.valueOf(2),java.math.BigInteger.ONE,java.math.BigInteger.valueOf(999),0,false);
        RowCopier.execute(pg,PortableSequence.create(Engine.POSTGRES,"tb_matrix","native_sequence",sequence));
        try(Statement query=pg.createStatement();ResultSet rs=query.executeQuery("SELECT nextval('tb_matrix.native_sequence'),nextval('tb_matrix.native_sequence')")){check(rs.next()&&rs.getLong(1)==21&&rs.getLong(2)==23,"native sequence next and increment work");}
        var oracleNumber=new CrossEngineDdl.Column("amount","NUMBER(10,2)",Types.NUMERIC,10,2,false,false,null,false);
        RowCopier.execute(pg,PortableType.create(Engine.ORACLE,Engine.POSTGRES,"tb_matrix","money_record",List.of(oracleNumber)));
        try(Statement query=pg.createStatement();ResultSet rs=query.executeQuery("SELECT (ROW(12.50)::tb_matrix.money_record).amount")){check(rs.next()&&rs.getBigDecimal(1).compareTo(new BigDecimal("12.50"))==0,"Oracle-style scalar object metadata builds PG composite");}
    }
    static void zoned(Connection pg)throws Exception{
        RowCopier.execute(pg,"CREATE TABLE tb_matrix.zoned_source(id integer PRIMARY KEY,z timestamptz(6))");
        RowCopier.execute(pg,"INSERT INTO tb_matrix.zoned_source VALUES(1,'2026-10-01 12:34:56.123456+08'),(2,NULL)");
        RowCopier.execute(pg,"SET TIME ZONE 'Asia/Shanghai'");
        try{
            for(boolean nativeDriver:List.of(false,true)){
                String target="tb_matrix.zoned_"+(nativeDriver?"native":"jdbc");RowCopier.execute(pg,"CREATE TABLE "+target+"(id integer PRIMARY KEY,z timestamptz(6))");
                Connection api=nativeDriver?remote(pg,Engine.POSTGRES):pg;
                check(RowCopier.copy(api,api,Engine.POSTGRES,Engine.POSTGRES,"tb_matrix.zoned_source",target,List.of("id","z"),false,List.of(),()->{},n->{})==2,"timestamp zone copy "+nativeDriver);
                try(Statement query=pg.createStatement();ResultSet rs=query.executeQuery("SELECT z AT TIME ZONE 'UTC' FROM "+target+" WHERE id=1")){check(rs.next()&&rs.getTimestamp(1).toLocalDateTime().equals(java.time.LocalDateTime.parse("2026-10-01T04:34:56.123456")),"timestamp instant preserved "+nativeDriver);}
                check(RowDigest.read(pg,Engine.POSTGRES,"tb_matrix.zoned_source",List.of("id","z"),List.of(Types.INTEGER,Types.TIMESTAMP_WITH_TIMEZONE),()->{}).equals(RowDigest.read(pg,Engine.POSTGRES,target,List.of("id","z"),List.of(Types.INTEGER,Types.TIMESTAMP_WITH_TIMEZONE),()->{})),"timestamp digest canonical instant "+nativeDriver);
            }
        }finally{RowCopier.execute(pg,"SET TIME ZONE 'UTC'");}
    }
    static void clock(Connection pg,Connection mysql)throws Exception{
        RowCopier.execute(pg,"CREATE TABLE tb_matrix.clock(id integer PRIMARY KEY,t time(6))");RowCopier.execute(pg,"INSERT INTO tb_matrix.clock VALUES(1,'12:34:56.123456'),(2,NULL)");
        for(Engine to:List.of(Engine.POSTGRES,Engine.MYSQL)){
            Connection target=to==Engine.MYSQL?mysql:pg;String table="tb_matrix.clock_"+to.name().toLowerCase(Locale.ROOT);
            RowCopier.execute(target,"CREATE TABLE "+table+"(id integer PRIMARY KEY,t time(6))");target.setAutoCommit(false);
            check(RowCopier.copy(remote(pg,Engine.POSTGRES),remote(target,to),Engine.POSTGRES,to,"tb_matrix.clock",table,List.of("id","t"),false,List.of(Types.INTEGER,Types.TIME),()->{},n->{})==2,"native TIME transfer "+to);
            try(Statement query=target.createStatement();ResultSet rs=query.executeQuery("SELECT t FROM "+table+" WHERE id=1")){check(rs.next()&&rs.getString(1).equals("12:34:56.123456"),"TIME microseconds preserved "+to);}
            check(RowDigest.read(pg,Engine.POSTGRES,"tb_matrix.clock",List.of("id","t"),List.of(Types.INTEGER,Types.TIME),()->{}).equals(RowDigest.read(target,to,table,List.of("id","t"),List.of(Types.INTEGER,Types.TIME),()->{})),"TIME digest agrees "+to);
            target.rollback();target.setAutoCommit(true);
        }
    }
    static void verifyDirectory(Connection connection,String sql,String expected)throws Exception{try(Statement q=connection.createStatement();ResultSet rs=q.executeQuery(sql)){check(rs.next()&&Path.of(rs.getString(1)).toRealPath().equals(Path.of(expected).toRealPath()),"task-owned database directory verified before writes");}}
    static CrossEngineDdl.Column col(String name,String type,int jdbc,int size,int scale,boolean identity){return new CrossEngineDdl.Column(name,type,jdbc,size,scale,name.equals("id"),identity,null,false);}
    static List<CrossEngineDdl.Column> columns(Engine source){return List.of(col("id","bigint",Types.BIGINT,19,0,true),col("amount",source==Engine.MYSQL?"decimal(20,4)":"numeric(20,4)",Types.NUMERIC,20,4,false),col("note","varchar(100)",Types.VARCHAR,100,0,false),col("payload",source==Engine.MYSQL?"blob":"bytea",Types.VARBINARY,0,0,false),col("created",source==Engine.MYSQL?"datetime(6)":"timestamp(6)",Types.TIMESTAMP,0,0,false),col("enabled","boolean",Types.BOOLEAN,0,0,false));}
    static void seed(Connection connection,Engine engine)throws Exception{try(PreparedStatement insert=connection.prepareStatement("INSERT INTO tb_matrix.source VALUES(?,?,?,?,?,?)")){for(int i=0;i<603;i++){insert.setLong(1,i);insert.setBigDecimal(2,new BigDecimal("1234567890123456.1234").add(BigDecimal.valueOf(i)));if(i%2==0)insert.setNull(3,Types.VARCHAR);else insert.setString(3,"中文🙂'"+i);insert.setBytes(4,new byte[]{0,(byte)255,(byte)i});insert.setTimestamp(5,Timestamp.valueOf("2026-10-01 12:34:56.123456"));insert.setBoolean(6,i%2==0);insert.addBatch();}insert.executeBatch();}}
    static Connection remote(Connection connection,Engine engine)throws Exception{var loader=CrossIntegration.class.getClassLoader();var helper=engine==Engine.MYSQL?new com.intellij.database.remote.jdbc.helpers.MysqlJdbcHelper("mysql","8.0.43",connection,loader):new com.intellij.database.remote.jdbc.helpers.PgJdbcHelper("18.3",connection,loader);return RemoteJdbc.connection(new com.intellij.database.remote.jdbc.impl.RemoteConnectionImpl(connection,helper));}
    static void exercise(Connection source,Connection target,Engine from,Engine to,String name,boolean useRemote)throws Exception{
        var ddl=CrossEngineDdl.build(from,to,"tb_matrix",name,columns(from),List.of("id"),Map.of(),Map.of("note","字段：O'Brien"));RowCopier.execute(target,ddl.sql());
        source.setAutoCommit(false);target.setAutoCommit(false);long start=System.nanoTime();
        long count=RowCopier.copy(useRemote?remote(source,from):source,useRemote?remote(target,to):target,from,to,"tb_matrix.source",to.qualified("tb_matrix",name),FIELDS,true,ddl.columns().stream().map(TransferPlan.Column::targetType).toList(),()->{},n->{});
        check(count==603,"603 rows copied "+name);
        var targetTypes=ddl.columns().stream().map(TransferPlan.Column::targetType).toList();
        RowDigest.Value expected=RowDigest.read(source,from,"tb_matrix.source",FIELDS,targetTypes,()->{}),actual=RowDigest.read(target,to,to.qualified("tb_matrix",name),FIELDS,targetTypes,()->{});
        check(expected.equals(actual),"full record digest matches across engines "+name);
        RowCopier.execute(target,"UPDATE "+to.qualified("tb_matrix",name)+" SET "+to.quote("amount")+"="+to.quote("amount")+"+1 WHERE "+to.quote("id")+"=1");
        check(!expected.equals(RowDigest.read(target,to,to.qualified("tb_matrix",name),FIELDS,targetTypes,()->{})),"digest catches changed data despite identical count "+name);
        RowCopier.execute(target,"UPDATE "+to.qualified("tb_matrix",name)+" SET "+to.quote("amount")+"="+to.quote("amount")+"-1 WHERE "+to.quote("id")+"=1");
        check(expected.equals(RowDigest.read(target,to,to.qualified("tb_matrix",name),FIELDS,targetTypes,()->{})),"digest remains valid after physical row order changes "+name);
        int rows=0;
        try(Statement q=target.createStatement();ResultSet rs=q.executeQuery("SELECT "+String.join(",",FIELDS.stream().map(to::quote).toList())+" FROM "+to.qualified("tb_matrix",name)+" ORDER BY "+to.quote("id"))){while(rs.next()){int id=rows++;check(rs.getLong(1)==id&&rs.getBigDecimal(2).compareTo(new BigDecimal("1234567890123456.1234").add(BigDecimal.valueOf(id)))==0&&Objects.equals(rs.getString(3),id%2==0?null:"中文🙂'"+id)&&Arrays.equals(rs.getBytes(4),new byte[]{0,(byte)255,(byte)id})&&rs.getTimestamp(5).getNanos()==123456000&&rs.getBoolean(6)==(id%2==0),"record fidelity "+name+" #"+id);}}
        check(rows==603,"exact target count "+name);target.rollback();check(TargetValidation.count(target,to.qualified("tb_matrix",name),to)==0,"caller rollback restored empty target "+name);
        RowCopier.copy(source,target,from,to,"tb_matrix.source",to.qualified("tb_matrix",name),FIELDS,true,ddl.columns().stream().map(TransferPlan.Column::targetType).toList(),()->{},n->{});target.commit();source.rollback();source.setAutoCommit(true);target.setAutoCommit(true);
        if(to!=Engine.MYSQL)RowCopier.execute(target,CrossStructure.comment(to,"tb_matrix",name,"note","字段：O'Brien"));
        String commentQuery=to==Engine.MYSQL?"SELECT COLUMN_COMMENT FROM information_schema.columns WHERE table_schema='tb_matrix' AND table_name='"+name+"' AND column_name='note'":"SELECT col_description('tb_matrix."+name+"'::regclass,3)";
        try(Statement query=target.createStatement();ResultSet rs=query.executeQuery(commentQuery)){check(rs.next(),"column comment metadata exists "+name);String actualComment=rs.getString(1);check(actualComment.equals("字段：O'Brien"),"column comment retained "+name+": "+actualComment);}
        RowCopier.execute(target,CrossStructure.check(to,"tb_matrix",name,name+"_positive","amount >= 0",Set.copyOf(FIELDS)));
        boolean checkRejected=false;try{RowCopier.execute(target,"UPDATE "+to.qualified("tb_matrix",name)+" SET amount=-1 WHERE id=1");}catch(SQLException invalidCheck){checkRejected=true;}check(checkRejected,"converted check enforced "+name);
        RowCopier.execute(target,CrossStructure.index(to,"tb_matrix",name,new CrossStructure.Index(name+"_note",List.of("note"),List.of(false),true)));
        RowCopier.execute(target,CrossStructure.comment(to,"tb_matrix",name,null,"中文 comment's text"));
        RowCopier.execute(target,"CREATE TABLE "+to.qualified("tb_matrix",name+"_child")+" (id bigint PRIMARY KEY,parent_id bigint)");
        RowCopier.execute(target,CrossStructure.foreignKey(to,"tb_matrix",name+"_child",new CrossStructure.ForeignKey(name+"_fk",List.of("parent_id"),name,List.of("id"),"CASCADE","NO_ACTION")));
        boolean rejected=false;try{RowCopier.execute(target,"INSERT INTO "+to.qualified("tb_matrix",name+"_child")+" VALUES(1,9999)");}catch(SQLException foreignKeyRejected){rejected=true;}check(rejected,"generated foreign key enforced "+name);
        String sourceView="CREATE VIEW "+from.qualified("src","v")+" AS SELECT source.id, 12.50 AS price FROM "+from.qualified("src","source")+" WHERE source.id >= 100;";
        var converted=PortableView.convert(from,to,"src","tb_matrix",name+"_view",sourceView,Map.of("source",name));
        RowCopier.execute(target,converted.sql());
        var chained=PortableView.convert(from,to,"src","tb_matrix",name+"_chain","SELECT v.id FROM src.v WHERE v.id >= 200",Map.of("v",name+"_view"));
        RowCopier.execute(target,chained.sql());
        check(TargetValidation.count(target,to.qualified("tb_matrix",name+"_view"),to)==503,"converted view uses renamed table "+name);
        check(TargetValidation.count(target,to.qualified("tb_matrix",name+"_chain"),to)==403,"converted dependent view uses target view "+name);
        try(Statement query=target.createStatement();ResultSet rs=query.executeQuery("SELECT price FROM "+to.qualified("tb_matrix",name+"_view"))){check(rs.next()&&rs.getBigDecimal(1).compareTo(new BigDecimal("12.50"))==0,"converted view decimal literal preserved "+name);}
        System.out.printf("%s -> %s %s: %d rows verified, %.3f s%n",from,to,useRemote?"native":"JDBC",count,(System.nanoTime()-start)/1e9);
    }
}
